"""Independent finite source-admission specification, not planner code.
Trusted profiles and validity views are supplied by the qualification harness.
"""
import json,hashlib

def canon(x):
    def check(v):
        if type(v) not in (dict,list,str,int,bool,type(None)):raise ValueError('JSON type')
        if type(v) is dict:
            if any(type(k) is not str for k in v):raise ValueError('key type')
            for y in v.values():check(y)
        if type(v) is list:
            for y in v:check(y)
    check(x)
    return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(x):return hashlib.sha256(canon(x)).hexdigest()
def eq(a,b):return canon(a)==canon(b)
def keys(x,k):return type(x) is dict and set(x)==set(k.split())
def fail(c):raise ValueError(c)
def check(ok,c):
    if not ok:fail(c)
def index(rows):
    check(type(rows) is list,'SCHEMA');d={}
    for r in rows:
        check(type(r) is dict and type(r.get('id')) is str and r['id'] not in d,'DUPLICATE_ID');d[r['id']]=r
    return d

def source(p,s,role):
    check(role in s['sources'],'SOURCE_MISSING');v=s['sources'][role]
    check(digest(v)==p['pins'][role],'SOURCE_PIN');return v

def current(p,validity,role,seen=()):
    check(role not in seen,'SOURCE_DEPENDENCY_CYCLE')
    check(validity['context']==p['context'],'VALIDITY_CONTEXT')
    check(set(validity['sources'])==set(p['pins']),'VALIDITY_INVENTORY')
    x=validity['sources'][role]
    check(x['identity']==p['pins'][role] and x['state'] in ['CURRENT','STALE','REVOKED'],'VALIDITY_TYPE')
    return x['state']=='CURRENT' and all(current(p,validity,dep,seen+(role,)) for dep in p['source_dependencies'][role])

def actions(p,s,v):
    rows=index(s['sources']['plan']['resolution_actions']);expected=p['definitions']
    check(set(rows)==set(expected),'ACTION_INVENTORY');out={}
    required='id primary_operation_class executor effect_boundary stage_role scope lineage prerequisite_actions external_prerequisites knowledge_requirements authority_requirements result_contract provenance'
    for aid,a in sorted(rows.items()):
        check(keys(a,required),'ACTION_SCHEMA');e=expected[aid]
        check(a['primary_operation_class']==e['primary_operation_class'],'OPERATION')
        check(a['stage_role']==e['stage_role'],'STAGE')
        check(a['executor']==e['executor'] and a['effect_boundary']==e['effect_boundary'],'EFFECT_EXECUTOR')
        check(a['scope']==e['scope'] and a['lineage']==e['lineage'],'SCOPE_LINEAGE')
        for pre in a['prerequisite_actions']:
            check(keys(pre,'domain id') and pre['domain']=='ActionId','PREREQUISITE_TYPE');check(pre['id'] in rows,'DANGLING_PREREQUISITE')
        check(eq(a['prerequisite_actions'],e['prerequisite_actions']) and eq(a['external_prerequisites'],e['external_prerequisites']),'PREREQUISITE_SET')
        check(eq(a['knowledge_requirements'],e['knowledge_requirements']),'KNOWLEDGE_REQUIREMENT')
        check(eq(a['authority_requirements'],e['authority_requirements']),'AUTHORITY_BINDING')
        check(eq(a['result_contract'],e['result_contract']),'RESULT_CONTRACT')
        check(eq(a['provenance'],e['provenance']),'PROVENANCE')
        check(current(p,v,'plan'),'STALE_ACTION_SOURCE')
        out[aid]=a
    source(p,s,'plan');return out

def history(p,s,v):
    plan=s['sources']['plan'];rows=index(plan['resolution_actions']);h=plan['execution_history'];results=index(s['sources']['results']['records'])
    check(h==p['history'],'HISTORY_ORDER_OR_SUBSTITUTION')
    check(set(results)==set(p['results']),'RESULT_INVENTORY')
    for rid,r in results.items():check(eq(r,p['results'][rid]),'RESULT_SUBSTITUTION')
    states={a:'PENDING' for a in rows};knowledge={};holds={}
    for n,event in enumerate(h):
        check(keys(event,'id sequence action result_id envelope ledger'),'HISTORY_SCHEMA')
        check(event['sequence']==n and event['action'] in rows and event['result_id'] in results,'HISTORY_REFERENCE')
        check(event['ledger']==p['context']['ledger'] and event['envelope']==p['context']['envelope'],'HISTORY_CONTEXT')
        r=results[event['result_id']];check(r['action']==event['action'],'RESULT_ACTION')
        check(r['outcome'] in ['PASS','BLOCKED','AUTHORITY_REQUIRED','EXTERNAL_GATE_REQUIRED','FAIL'],'RESULT_OUTCOME')
        states[r['action']]='COMPLETED' if r['outcome']=='PASS' else 'BLOCKED'
        for k in r['knowledge']:
            check(k['id'] not in knowledge,'KNOWLEDGE_CONFLICT')
            check(k['source'] in p['pins'],'KNOWLEDGE_SOURCE')
            knowledge[k['id']]={'producer':r['action'],'outcome':r['outcome'],'type':k['type'],'current':current(p,v,k['source']) and current(p,v,'results'),'source':k['source']}
        for hold in r['holds']:holds[hold['id']]=hold
    # Imported holds require an independently admitted override, never last-file wins.
    check(plan['overrides']==p['overrides'],'OVERRIDE_BINDING')
    for override in plan['overrides']:
        check(override['hold'] in holds and override['source'] in p['pins'] and current(p,v,override['source']),'OVERRIDE_SUPPORT')
        check(holds[override['hold']]['action']==override['action'],'OVERRIDE_ACTION')
        del holds[override['hold']]
    check(eq(plan['execution_state'],{'action_states':states,'holds':sorted(holds.values(),key=lambda x:x['id'])}),'CURRENT_SUMMARY_CONFLICT')
    eligible=[]
    for aid,a in sorted(rows.items()):
        if states[aid]!='PENDING' or any(x['action']==aid for x in holds.values()) or not current(p,v,'plan'):continue
        if a['external_prerequisites'] or a['authority_requirements']:continue
        if any(states[x['id']]!='COMPLETED' or not current(p,v,'results') or any(not k['current'] for k in knowledge.values() if k['producer']==x['id']) for x in a['prerequisite_actions']):continue
        if any(k not in knowledge or not knowledge[k]['current'] or knowledge[k]['type']!=typ for k,typ in a['knowledge_requirements'].items()):continue
        eligible.append(aid)
    source(p,s,'plan');source(p,s,'results')
    source(p,s,'evidence');source(p,s,'override')
    return {'historical_states':states,'knowledge':knowledge,'holds':sorted(holds),'prerequisite_eligible':eligible}

def graph(p,s,v):
    g=s['sources']['graph'];check(keys(g,'schema id entities assertions predicates'),'GRAPH_SCHEMA');check(g['schema']=='PF-SOURCE-GRAPH-1' and g['id']==p['graph_id'],'GRAPH_ID')
    entities=index(g['entities']); assertions=index(g['assertions']);predicates=index(g['predicates'])
    check(set(entities)==set(p['entities']) and set(assertions)==set(p['assertions']) and set(predicates)==set(p['predicates']),'GRAPH_INVENTORY')
    for eid,e in entities.items():
        check(eq(e,p['entities'][eid]),'ENTITY_DOMAIN_OR_CONTEXT')
    accepted=[];descriptive=[];edges=[];seen={}
    for aid,a in sorted(assertions.items()):
        check(keys(a,'id subject object relation assertion_class establishes_ordering projection_layer provenance evidence predicate context claim'),'ASSERTION_SCHEMA')
        check(a['subject'] in entities and a['object'] in entities,'DANGLING_ENTITY')
        check(a['predicate'] in predicates,'DANGLING_PREDICATE')
        check(a['relation'] in p['relations'],'UNKNOWN_RELATION')
        check(a['context']==p['context'],'GRAPH_CONTEXT')
        check(a['provenance']==p['assertions'][aid]['provenance'],'ASSERTION_PROVENANCE')
        for ref in a['evidence']:check(ref in p['pins'],'DANGLING_EVIDENCE')
        key=(a['subject'],a['relation'],a['object'])
        check(key not in seen or seen[key]==a['claim'],'ASSERTION_CONFLICT');seen[key]=a['claim']
        check(type(a['establishes_ordering']) is bool,'ORDERING_TYPE')
        operative=a['assertion_class'] in ['DETERMINISTIC_EXTRACTED','ARTIFACT_REPORTED'] and a['projection_layer'] in ['EXISTING_BASELINE','READINESS_GATES','CLOSURE_ANALYSIS'] and a['provenance']['admission']=='ACCEPTED'
        if a['establishes_ordering']:check(a['relation']=='REQUIRES','ILLEGAL_ORDERING')
        check(eq(a,p['assertions'][aid]) and eq(predicates[a['predicate']],p['predicates'][a['predicate']]),'ASSERTION_RULE')
        if operative:
            check(current(p,v,'graph') and all(current(p,v,x) for x in a['evidence']),'STALE_REQUIRED_ASSERTION')
            accepted.append(aid)
            if a['establishes_ordering']:edges.append([a['object'],a['subject']])
        else:descriptive.append(aid)
    # canonical typed-ID topological projection, cycle => reject.
    remaining=set(entities);order=[]
    while remaining:
        ready=sorted(x for x in remaining if not any(b==x and a in remaining for a,b in edges))
        check(bool(ready),'ORDERING_CYCLE');order+=ready;remaining-=set(ready)
    source(p,s,'graph');source(p,s,'evidence')
    return {'accepted_assertions':accepted,'descriptive_assertions':descriptive,'edges':sorted(edges),'order':order}

def evaluate(p,s,v,family='INSTANCE'):
    try:
        check(keys(s,'schema mode profile_pin context sources coverage admissions'),'SCHEMA')
        check(s['schema']=='PF-INPUT-1' and s['mode']=='SYNTHETIC_QUALIFICATION_ONLY' and s['profile_pin']==digest(p),'PROFILE')
        check(eq(s['context'],p['context']),'INSTANCE_CONTEXT')
        if family=='ACTION':out=actions(p,s,v)
        elif family=='HISTORY':out=history(p,s,v)
        elif family=='GRAPH':out=graph(p,s,v)
        elif family=='INSTANCE':
            check(set(s['sources'])==set(p['pins']),'INSTANCE_MEMBERS')
            check(all(current(p,v,r) for r in p['pins']),'MIXED_STALE_INSTANCE')
            for role in s['sources']:source(p,s,role)
            check(eq(s['coverage'],p['coverage']),'COVERAGE')
            check(eq(s['admissions'],p['admissions']),'ADMISSION_BINDINGS')
            # O08/O09 proof evaluations MUST be performed separately by the fixed
            # reference oracles pinned in profile; these are evidence bindings,
            # never free-standing accepted booleans. Composition evaluator below
            # additionally requires their independently recomputed outcomes.
            out={'actions':actions(p,s,v),'history':history(p,s,v),'graph':graph(p,s,v)}
        else:fail('UNKNOWN_FAMILY')
        return {'accepted':True,'failed_clause':None,'output':out}
    except (KeyError,TypeError,ValueError,IndexError) as e:return {'accepted':False,'failed_clause':str(e),'output':None}

def compose(p,s,v,reference_programs,submissions):
    # Qualification harness supplies independently pinned specification programs.
    # A runtime must NOT execute code selected by imported source artifacts.
    out=evaluate(p,s,v,'INSTANCE')
    if not out['accepted']:return out
    try:
        check(set(reference_programs)=={'O08','O09'} and set(submissions)==set(p['admissions']),'ADMISSION_INVENTORY')
        for role,program in reference_programs.items():check(hashlib.sha256(program.encode()).hexdigest()==p['oracle_program_pins'][role],'ORACLE_PIN')
        for key,entry in submissions.items():
            binding=p['admissions'][key];check(digest(entry)==binding['submission_digest'],'ADMISSION_SUBSTITUTION')
            check(binding['graph']==p['context']['base_graph'],'ADMISSION_GRAPH')
            ns={};exec(reference_programs[binding['family']],ns)
            if binding['family']=='O08':
                check(entry['profile']['context']['graph']==p['context']['base_graph'],'ADMISSION_GRAPH')
                check(entry['profile']['context']['plan']==p['context']['base_plan'] and entry['profile']['context']['selection_policy']==p['context']['policy'],'ADMISSION_CONTEXT')
                result=ns['admit'](entry['profile'],entry['state'],entry['validity'])
            else:
                check(entry['profile']['snapshot']==p['context']['base_graph'],'ADMISSION_GRAPH')
                check(entry['profile']['envelope']==p['context']['envelope'],'ADMISSION_ENVELOPE')
                result=ns['admit'](entry['profile'],entry['state'],entry['validity'])
            check(result['accepted'],'ADMISSION_REJECTED')
        return out
    except (KeyError,TypeError,ValueError) as e:return {'accepted':False,'failed_clause':str(e),'output':None}
